SELECT percentile_cont(0.25) within GROUP (ORDER BY l.value) AS percentile_25, (SELECT COUNT(*) FROM male_labevents)::FLOAT / NULLIF((SELECT COUNT(*) FROM labevents), 0) AS fraction_of_total_labevents, AVG(l.los) AS average_length_of_stay, (SELECT COUNT(*) FROM male_labevents WHERE l.flag = 'C')::FLOAT / NULLIF((SELECT COUNT(*) FROM labevents), 0) AS fraction_of_total_critical_labevents FROM male_labevent_data l;